/**
 * Drives a real, live multi-turn adaptive interview against four canned
 * pilot personas (commuter, local, pay-focused, lifestyle-focused) and
 * dumps the full transcript + final profile for each to stdout (and to a
 * `.md` file per persona under this script's own directory) — the concrete
 * mechanism for Phase 2's "test against text transcripts before building
 * UI" requirement, and reused unchanged for Phase 6's pilot-review ask.
 *
 * Answers are hardcoded per persona, not generated by another LLM — this
 * tests the interview against realistic pilot answers, not the model
 * against itself. Since the interview branches dynamically, an answer
 * "matcher" makes a best-effort persona-appropriate choice for whatever
 * question actually comes back, falling back to a generic response for
 * anything a persona's own script didn't anticipate.
 *
 * Usage: npx tsx scripts/run-adaptive-interview-transcript.ts [persona...]
 * (no args runs all four). Requires ANTHROPIC_API_KEY in the environment —
 * never run in CI.
 */

import { writeFile } from "node:fs/promises";
import path from "node:path";
import { computeBidPackGroundingStats } from "../src/lib/interview-grounding";
import {
  applyProfileUpdates,
  buildTurnRequest,
  finalizeAdaptiveProfile,
  HARD_CEILING_TURNS,
} from "../src/lib/interview-engine";
import { runInterviewTurn } from "../src/lib/interview-turn-service";
import { SAMPLE_BID_PACK } from "../src/lib/sample-bidpack";
import type {
  InterviewAnswer,
  InterviewQuestion,
  InterviewTurnRecord,
  PreferenceFact,
} from "../src/types/interview-session";
import type { CitySentiment } from "../src/types/preferences";

interface Persona {
  name: string;
  isCommuter: boolean;
  hasCrashPad: boolean | null;
  /** boundTo -> slider value (-100..100). Missing keys fall back to 0 (no strong preference). */
  sliderLeanings: Partial<Record<string, number>>;
  /** boundTo -> fraction of the bid pack's real range (0 = min, 1 = max). Missing keys fall back to 0.5. */
  targetLeanings: Partial<Record<string, number>>;
  /** Case-insensitive keywords this persona's choice-question answer should favor, checked against each option's label+description. */
  choiceKeywords: string[];
  /** Canned free-text answers, tried in order against the question prompt's own keywords; the last entry has no keyword and is the fallback. */
  freeTextAnswers: { keyword?: string; text: string }[];
  /**
   * Real IATA-style codes from SAMPLE_BID_PACK's own layover cities
   * (LAX/CDG/HNL) — mirrors the city picker's real pre-loop step
   * (`AdaptiveInterview.tsx`'s `factsFromCityPreferences`), which every
   * canned persona run before this one skipped entirely (this script never
   * simulated it), so none of them ever got a chance to exercise the
   * "why" follow-up or city-reason tagging the real UI always has a shot
   * at. Absent means no cities seeded, exactly like before.
   */
  citySeed?: Record<string, CitySentiment>;
}

/** Mirrors `AdaptiveInterview.tsx`'s own `factsFromCityPreferences` exactly — kept as a separate small copy here since that one lives in a "use client" component file this Node script can't import from. */
function factsFromCitySeed(citySeed: Record<string, CitySentiment>): PreferenceFact[] {
  return Object.entries(citySeed).map(([code, sentiment]) => ({
    id: crypto.randomUUID(),
    statement: `${sentiment === "love" ? "Loves" : "Wants to avoid"} layovers in ${code}.`,
    kind: "measurable",
    measurable: { type: "city-sentiment", code, sentiment },
    confidence: 1,
    importance: 0.6,
    source: { kind: "seed-question", questionKey: "cities" },
    turnIndex: 0,
  }));
}

