function pickSliderValue(persona: Persona, boundTo: string): number {
  return persona.sliderLeanings[boundTo] ?? 0;
}

function pickTargetValue(persona: Persona, boundTo: string, min: number, max: number): number {
  const fraction = persona.targetLeanings[boundTo] ?? 0.5;
  return Math.round(min + (max - min) * fraction);
}

function pickChoiceIndex(persona: Persona, options: { label: string; description?: string }[]): number {
  let bestIndex = 0;
  let bestScore = -1;
  options.forEach((opt, i) => {
    const text = `${opt.label} ${opt.description ?? ""}`.toLowerCase();
    const score = persona.choiceKeywords.filter((kw) => text.includes(kw.toLowerCase())).length;
    if (score > bestScore) {
      bestScore = score;
      bestIndex = i;
    }
  });
  return bestIndex;
}

function pickFreeText(persona: Persona, prompt: string): string {
  const lower = prompt.toLowerCase();
  const match = persona.freeTextAnswers.find((a) => a.keyword && lower.includes(a.keyword));
  return (match ?? persona.freeTextAnswers[persona.freeTextAnswers.length - 1]).text;
}

function answerQuestion(persona: Persona, question: InterviewQuestion, creditRange: { min: number; max: number }): InterviewAnswer {
  switch (question.kind) {
    case "slider":
      return { kind: "slider", value: pickSliderValue(persona, question.boundTo) };
    case "target-slider": {
      // circadianTolerance is a small, fixed [0, 4] "how many consecutive
      // early reports" count — not a bid-pack-derived range. Mirrors
      // `AdaptiveInterview.tsx`'s own `CIRCADIAN_TOLERANCE_RANGE`, which this
      // harness previously ignored (falling through to the generic 4-20
      // default and producing nonsensical values like "12 in a row").
      const range =
        question.boundTo === "creditHours"
          ? creditRange
          : question.boundTo === "circadianTolerance"
            ? { min: 0, max: 4 }
            : { min: 4, max: 20 };
      return { kind: "target-slider", value: pickTargetValue(persona, question.boundTo, range.min, range.max) };
    }
    case "choice":
      return { kind: "choice", selectedIndex: pickChoiceIndex(persona, question.options) };
    case "free-text":
      return { kind: "free-text", text: pickFreeText(persona, question.prompt) };
    case "wrap-up":
      return { kind: "skipped" };
  }
}

function formatAnswer(question: InterviewQuestion, answer: InterviewAnswer): string {
  if (answer.kind === "choice" && question.kind === "choice") {
    return question.options[answer.selectedIndex]?.label ?? "(invalid choice)";
  }
  if (answer.kind === "slider") return String(answer.value);
  if (answer.kind === "target-slider") return String(answer.value);
  if (answer.kind === "free-text") return answer.text;
  return "(skipped)";
}

async function runPersona(persona: Persona): Promise<string> {
  const apiKey = process.env.ANTHROPIC_API_KEY;
  if (!apiKey) throw new Error("ANTHROPIC_API_KEY is not set.");

  const grounding = computeBidPackGroundingStats(SAMPLE_BID_PACK);
  let transcript: InterviewTurnRecord[] = [];
  let facts: PreferenceFact[] = persona.citySeed ? factsFromCitySeed(persona.citySeed) : [];
  let turnsUsed = 0;
  const lines: string[] = [`# Adaptive interview transcript — persona: ${persona.name}\n`];

  while (turnsUsed < HARD_CEILING_TURNS) {
    const request = buildTurnRequest({
      transcript,
      facts,
      grounding,
      base: SAMPLE_BID_PACK.base,
      aircraft: SAMPLE_BID_PACK.aircraft,
      isCommuter: persona.isCommuter,
      turnsUsed,
    });

    const result = await runInterviewTurn(apiKey, request);
    if (!result.ok) {
      lines.push(`\n**Turn ${turnsUsed + 1} failed: ${result.error}**\n`);
      break;
    }
    const { turn } = result;
    facts = applyProfileUpdates(facts, turn.profileUpdates);

    if (turn.reasoning) {
      lines.push(`\n_Reasoning: ${turn.reasoning}_`);
    }

    if (turn.action === "wrap_up" || !turn.question) {
      lines.push(`\n**Interview wrapped up after ${turnsUsed} question${turnsUsed === 1 ? "" : "s"}.**\n`);
      break;
    }

    const answer = answerQuestion(persona, turn.question, grounding.creditHours);
    lines.push(`\n**Q${turnsUsed + 1} (${turn.question.kind}):** ${turn.question.prompt}`);
    if (turn.question.kind === "slider") {
      lines.push(`_(${turn.question.lowLabel} .. ${turn.question.centerLabel} .. ${turn.question.highLabel})_`);
    }
    lines.push(`**A:** ${formatAnswer(turn.question, answer)}`);

    transcript = [
      ...transcript,
      { turnIndex: turnsUsed, question: turn.question, answer, profileFactIdsTouched: [] },
    ];
    turnsUsed++;
  }

  if (turnsUsed >= HARD_CEILING_TURNS) {
    lines.push(`\n**Hit the hard turn ceiling (${HARD_CEILING_TURNS}) — stopped client-side regardless of model intent.**\n`);
  }

  const profile = finalizeAdaptiveProfile({
    facts,
    transcript,
    isCommuter: persona.isCommuter,
    hasCrashPad: persona.hasCrashPad,
    cityPreferencesSeed: persona.citySeed,
  });

  lines.push(`\n## Final profile\n`);
  lines.push("```json");
  lines.push(
    JSON.stringify(
      {
        weights: profile.weights,
        explicitTargets: profile.explicitTargets,
        cityPreferences: profile.cityPreferences,
        implicitWeights: profile.implicitWeights,
        qualitativeFacts: profile.discoveredFacts.filter((f) => f.kind === "qualitative").map((f) => f.statement),
        dealbreakers: profile.discoveredFacts
          .filter((f) => f.severity === "dealbreaker")
          .map((f) => ({ statement: f.statement, measurable: f.measurable })),
      },
      null,
      2
    )
  );
  lines.push("```");

  return lines.join("\n");
}

async function main() {
  const requested = process.argv.slice(2);
  const personas = requested.length > 0 ? PERSONAS.filter((p) => requested.includes(p.name)) : PERSONAS;
  if (personas.length === 0) {
    console.error(`No matching persona. Available: ${PERSONAS.map((p) => p.name).join(", ")}`);
    process.exit(1);
  }

  for (const persona of personas) {
    console.log(`\n=== Running persona: ${persona.name} ===`);
    const transcript = await runPersona(persona);
    console.log(transcript);
    const outPath = path.join(__dirname, `transcript-${persona.name}.md`);
    await writeFile(outPath, transcript, "utf-8");
    console.log(`\n(written to ${outPath})`);
  }
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});
